/**
 * Web Push primitives (UI-160), Web Crypto only: no `node:` imports and no Deno globals, so the same code
 * runs in the Supabase Edge Functions (Deno) and in the Node unit tests (`npm test`).
 *
 *  - RFC 8291 message encryption (`Content-Encoding: aes128gcm`), checked against the RFC 8291 Appendix A vector.
 *  - RFC 8292 VAPID: an ES256 JWT plus the `vapid t=<jwt>, k=<public key>` Authorization header, checked against
 *    the RFC 8292 example token.
 *  - VAPID key pair generation (P-256) and a tiny sender for the push service POST.
 *
 * The VAPID private key is generated by `getOrCreateVapid` the first time anything needs it and kept in a
 * service-only table (`push_vapid_snacc`); nobody ever types or pastes it.
 */

import { concatBytes, toArrayBuffer, utf8 } from "./nep413.ts";

// ---------------------------------------------------------------------------------------------
// base64url
// ---------------------------------------------------------------------------------------------

export function b64uEncode(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Strict base64url (no `+` or `/`; trailing `=` tolerated). `null` when the text is not valid base64url. */
export function b64uDecode(s: string): Uint8Array | null {
  if (typeof s !== "string" || !/^[A-Za-z0-9_-]*={0,2}$/.test(s)) return null;
  const clean = s.replace(/=+$/, "");
  if (clean.length % 4 === 1) return null;
  try {
    const bin = atob(clean.replace(/-/g, "+").replace(/_/g, "/"));
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------------------------
// RFC 8291 encryption
// ---------------------------------------------------------------------------------------------

/** Default record size (RFC 8188); the whole push message must stay below the push service limit of 4096 octets. */
export const RECORD_SIZE = 4096;
/** Header (16 salt + 4 rs + 1 idlen + 65 key) plus delimiter plus GCM tag. */
const HEADER_LEN = 16 + 4 + 1 + 65;
export const MAX_PLAINTEXT_BYTES = RECORD_SIZE - HEADER_LEN - 1 - 16;

const subtle = (): SubtleCrypto => globalThis.crypto.subtle;
const P256 = { name: "ECDH", namedCurve: "P-256" } as const;

async function hkdf(salt: Uint8Array, ikm: Uint8Array, info: Uint8Array, bytes: number): Promise<Uint8Array> {
  const key = await subtle().importKey("raw", toArrayBuffer(ikm), "HKDF", false, ["deriveBits"]);
  const bits = await subtle().deriveBits({ name: "HKDF", hash: "SHA-256", salt: toArrayBuffer(salt), info: toArrayBuffer(info) }, key, bytes * 8);
  return new Uint8Array(bits);
}

export interface SenderKey {
  /** Uncompressed P-256 point, 65 bytes (`0x04 ‖ X ‖ Y`). */
  publicKey: Uint8Array;
  /** 32-byte private scalar. */
  d: Uint8Array;
}

export interface EncryptOptions {
  /** 16 random bytes; tests pin it to the RFC vector. */
  salt?: Uint8Array;
  /** Ephemeral sender key; tests pin it to the RFC vector. Omit in production (a fresh key is generated). */
  senderKey?: SenderKey;
}

async function ephemeralKey(): Promise<{ privateKey: CryptoKey; publicRaw: Uint8Array }> {
  const pair = await subtle().generateKey(P256, true, ["deriveBits"]);
  const publicRaw = new Uint8Array(await subtle().exportKey("raw", pair.publicKey));
  return { privateKey: pair.privateKey, publicRaw };
}

async function importSenderKey(k: SenderKey): Promise<CryptoKey> {
  const jwk: JsonWebKey = {
    kty: "EC",
    crv: "P-256",
    x: b64uEncode(k.publicKey.slice(1, 33)),
    y: b64uEncode(k.publicKey.slice(33, 65)),
    d: b64uEncode(k.d),
    ext: true,
  };
  return subtle().importKey("jwk", jwk, P256, false, ["deriveBits"]);
}

/** Is `raw` a valid uncompressed P-256 public key (on the curve)? */
export async function isValidP256PublicKey(raw: Uint8Array): Promise<boolean> {
  if (raw.length !== 65 || raw[0] !== 0x04) return false;
  try {
    await subtle().importKey("raw", toArrayBuffer(raw), P256, false, []);
    return true;
  } catch {
    return false;
  }
}

/**
 * RFC 8291 §3.4: encrypt `plaintext` for one subscription (`uaPublic` = `p256dh`, 65 bytes; `authSecret` = `auth`, 16 bytes)
 * and return the full request body (RFC 8188 header ‖ one encrypted record).
 */
export async function encryptWebPush(plaintext: Uint8Array, uaPublic: Uint8Array, authSecret: Uint8Array, opts: EncryptOptions = {}): Promise<Uint8Array> {
  if (plaintext.length > MAX_PLAINTEXT_BYTES) throw new Error(`push payload too large (${plaintext.length} > ${MAX_PLAINTEXT_BYTES} bytes)`);
  if (authSecret.length !== 16) throw new Error("auth secret must be 16 bytes");
  if (!(await isValidP256PublicKey(uaPublic))) throw new Error("p256dh is not a valid P-256 public key");
  const salt = opts.salt ?? globalThis.crypto.getRandomValues(new Uint8Array(16));
  if (salt.length !== 16) throw new Error("salt must be 16 bytes");

  let senderPrivate: CryptoKey;
  let asPublic: Uint8Array;
  if (opts.senderKey) {
    senderPrivate = await importSenderKey(opts.senderKey);
    asPublic = opts.senderKey.publicKey;
  } else {
    const e = await ephemeralKey();
    senderPrivate = e.privateKey;
    asPublic = e.publicRaw;
  }

  const uaKey = await subtle().importKey("raw", toArrayBuffer(uaPublic), P256, false, []);
  const ecdhSecret = new Uint8Array(await subtle().deriveBits({ name: "ECDH", public: uaKey }, senderPrivate, 256));

  // PRK_key = HMAC(auth_secret, ecdh_secret); IKM = HMAC(PRK_key, key_info ‖ 0x01)  ==  HKDF(auth_secret, ecdh_secret, key_info, 32)
  const keyInfo = concatBytes(utf8("WebPush: info\0"), uaPublic, asPublic);
  const ikm = await hkdf(authSecret, ecdhSecret, keyInfo, 32);
  const cek = await hkdf(salt, ikm, utf8("Content-Encoding: aes128gcm\0"), 16);
  const nonce = await hkdf(salt, ikm, utf8("Content-Encoding: nonce\0"), 12);

  const record = concatBytes(plaintext, new Uint8Array([0x02])); // 0x02 = last-record padding delimiter
  const aesKey = await subtle().importKey("raw", toArrayBuffer(cek), "AES-GCM", false, ["encrypt"]);
  const cipher = new Uint8Array(await subtle().encrypt({ name: "AES-GCM", iv: toArrayBuffer(nonce), tagLength: 128 }, aesKey, toArrayBuffer(record)));

  const rs = new Uint8Array(4);
  new DataView(rs.buffer).setUint32(0, RECORD_SIZE, false);
  return concatBytes(salt, rs, new Uint8Array([asPublic.length]), asPublic, cipher);
}

// ---------------------------------------------------------------------------------------------
// RFC 8292 VAPID
// ---------------------------------------------------------------------------------------------

export interface VapidKeys {
  /** base64url of the uncompressed public key (the `applicationServerKey` the browser subscribes with). */
  publicKey: string;
  /** P-256 private key as a JWK (`kty`, `crv`, `x`, `y`, `d`). Never leaves the service-only table. */
  privateJwk: JsonWebKey;
}

/** Generate a fresh VAPID key pair with Web Crypto. */
export async function generateVapidKeys(): Promise<VapidKeys> {
  const pair = await subtle().generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const jwk = await subtle().exportKey("jwk", pair.privateKey);
  const raw = new Uint8Array(await subtle().exportKey("raw", pair.publicKey));
  return { publicKey: b64uEncode(raw), privateJwk: { kty: "EC", crv: "P-256", x: jwk.x, y: jwk.y, d: jwk.d } };
}

export const VAPID_JWT_TTL_SEC = 12 * 3600; // RFC 8292 §2: exp must be within 24 hours
export const DEFAULT_VAPID_SUBJECT = "https://snacc-nu.vercel.app";

export interface VapidClaimsInput {
  /** Origin of the push service the request goes to, e.g. `https://fcm.googleapis.com`. */
  audience: string;
  /** `mailto:` or `https:` contact URI. */
  subject: string;
  nowSec: number;
  ttlSec?: number;
}

/** ES256 JWT `header.claims.signature`, signature in the raw `r ‖ s` form JWT requires. */
export async function signVapidJwt(input: VapidClaimsInput, privateJwk: JsonWebKey): Promise<string> {
  const header = b64uEncode(utf8(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const claims = b64uEncode(utf8(JSON.stringify({ aud: input.audience, exp: input.nowSec + (input.ttlSec ?? VAPID_JWT_TTL_SEC), sub: input.subject })));
  const key = await subtle().importKey("jwk", { ...privateJwk, ext: true }, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const sig = new Uint8Array(await subtle().sign({ name: "ECDSA", hash: "SHA-256" }, key, toArrayBuffer(utf8(`${header}.${claims}`))));
  return `${header}.${claims}.${b64uEncode(sig)}`;
}

export interface VapidClaims {
  aud: string;
  exp: number;
  sub: string;
}

/** Verify an ES256 VAPID JWT against `publicKey` (base64url, 65 bytes). Returns the claims, or `null` when anything is off. */
export async function verifyVapidJwt(jwt: string, publicKey: string, nowSec?: number): Promise<VapidClaims | null> {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  const [h, c, s] = parts as [string, string, string];
  const sig = b64uDecode(s);
  const raw = b64uDecode(publicKey);
  if (!sig || sig.length !== 64 || !raw || raw.length !== 65) return null;
  let header: unknown;
  let claims: unknown;
  try {
    header = JSON.parse(new TextDecoder().decode(b64uDecode(h) ?? new Uint8Array()));
    claims = JSON.parse(new TextDecoder().decode(b64uDecode(c) ?? new Uint8Array()));
  } catch {
    return null;
  }
  const hd = header as { alg?: unknown; typ?: unknown } | null;
  const cl = claims as Partial<VapidClaims> | null;
  if (!hd || hd.alg !== "ES256" || !cl || typeof cl.aud !== "string" || typeof cl.sub !== "string" || typeof cl.exp !== "number") return null;
  if (nowSec !== undefined && cl.exp <= nowSec) return null;
  try {
    const key = await subtle().importKey("raw", toArrayBuffer(raw), { name: "ECDSA", namedCurve: "P-256" }, false, ["verify"]);
    const ok = await subtle().verify({ name: "ECDSA", hash: "SHA-256" }, key, toArrayBuffer(sig), toArrayBuffer(utf8(`${h}.${c}`)));
    return ok ? { aud: cl.aud, exp: cl.exp, sub: cl.sub } : null;
  } catch {
    return null;
  }
}

/** RFC 8292 §3: `Authorization: vapid t=<jwt>, k=<public key>`. */
export function vapidAuthorization(jwt: string, publicKey: string): string {
  return `vapid t=${jwt}, k=${publicKey}`;
}

/** `https://host` of a push endpoint (the JWT `aud`). */
export function audienceOf(endpoint: string): string {
  return new URL(endpoint).origin;
}

// ---------------------------------------------------------------------------------------------
// VAPID key lifecycle: generated once, inside the backend
// ---------------------------------------------------------------------------------------------

export interface VapidStore {
  read(): Promise<VapidKeys | null>;
  /** Insert only when no key exists yet (`ON CONFLICT DO NOTHING`), so concurrent first uses cannot overwrite each other. */
  insertIfAbsent(keys: VapidKeys): Promise<void>;
}

/**
 * Return the stored VAPID key pair, generating it on first use. Two functions racing on the very first call may
 * both generate a key, but only one insert wins; both then re-read and use the winner.
 */
export async function getOrCreateVapid(store: VapidStore, generate: () => Promise<VapidKeys> = generateVapidKeys): Promise<VapidKeys> {
  const existing = await store.read();
  if (existing) return existing;
  await store.insertIfAbsent(await generate());
  const winner = await store.read();
  if (!winner) throw new Error("push_vapid_snacc: key was not stored");
  return winner;
}

// ---------------------------------------------------------------------------------------------
// Sending
// ---------------------------------------------------------------------------------------------

export type SendOutcome =
  | { kind: "ok"; status: number }
  /** 404 / 410: the push service says the subscription no longer exists. */
  | { kind: "gone"; status: number }
  | { kind: "error"; status: number | null; message: string };

export interface SendOptions {
  /** `Authorization` header value (`vapidAuthorization(...)`). */
  authorization: string;
  /** Seconds the push service may hold the message while the device is offline. */
  ttl?: number;
  urgency?: "very-low" | "low" | "normal" | "high";
  fetchFn?: (input: string, init: RequestInit) => Promise<Response>;
  timeoutMs?: number;
  senderKey?: SenderKey;
  salt?: Uint8Array;
}

export interface SendTarget {
  endpoint: string;
  /** base64url `p256dh` (65 bytes) and `auth` (16 bytes) as stored. */
  p256dh: string;
  auth: string;
}

/** Encrypt `payload` and POST it to the subscription's push service. Never throws: failures become a `SendOutcome`. */
export async function sendWebPush(target: SendTarget, payload: string, opts: SendOptions): Promise<SendOutcome> {
  const ua = b64uDecode(target.p256dh);
  const auth = b64uDecode(target.auth);
  if (!ua || !auth) return { kind: "error", status: null, message: "stored keys are not valid base64url" };
  let body: Uint8Array;
  try {
    body = await encryptWebPush(utf8(payload), ua, auth, { senderKey: opts.senderKey, salt: opts.salt });
  } catch (e) {
    return { kind: "error", status: null, message: e instanceof Error ? e.message.slice(0, 160) : "encryption failed" };
  }
  const fetchFn = opts.fetchFn ?? ((i, init) => fetch(i, init));
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 8000);
  try {
    const res = await fetchFn(target.endpoint, {
      method: "POST",
      headers: {
        Authorization: opts.authorization,
        "Content-Encoding": "aes128gcm",
        "Content-Type": "application/octet-stream",
        TTL: String(opts.ttl ?? 6 * 3600),
        Urgency: opts.urgency ?? "normal",
      },
      body: toArrayBuffer(body),
      signal: controller.signal,
      redirect: "manual",
    });
    // Drain so the connection can be reused; the body is not needed.
    await res.arrayBuffer().catch(() => undefined);
    if (res.status >= 200 && res.status < 300) return { kind: "ok", status: res.status };
    if (res.status === 404 || res.status === 410) return { kind: "gone", status: res.status };
    return { kind: "error", status: res.status, message: `push service answered ${res.status}` };
  } catch (e) {
    return { kind: "error", status: null, message: e instanceof Error && e.name === "AbortError" ? "push service timed out" : "push service unreachable" };
  } finally {
    clearTimeout(timer);
  }
}
